4	/** Format integer cents as a fixed 2-decimal string, e.g. 1005 -> "10.05". */
5	export function formatCents(cents: number): string {
6	  if (!Number.isInteger(cents)) {
7	    throw new Error(`formatCents expects an integer number of cents, got ${cents}`);
8	  }
9	  const sign = cents < 0 ? "-" : "";
10	  const abs = Math.abs(cents);
11	  const whole = Math.floor(abs / 100);
12	  const frac = String(abs % 100).padStart(2, "0");
